// @req: REQ-012
const assert = require('assert');
const unalib = require('../../libs/unalib');

describe('REQ-012 (Unit) — Límite de 280 caracteres en unalib', function () {
  it('debe rechazar mensajes que superen los 280 caracteres', function () {
    const longMsg = 'a'.repeat(281);
    const res = unalib.validateMessage({ mensaje: longMsg, nombre: 'Usuario', color: '#000000' });
    assert.strictEqual(res === false || res === null || (res && res.valid === false) || (res && res.mensaje && res.mensaje.length > 280), false, 'Mensaje > 280 caracteres no debe ser aceptado tal cual');
  });
  it('debe aceptar mensajes de hasta 280 caracteres exactos', function () {
    const exactMsg = 'a'.repeat(280);
    const res = unalib.validateMessage({ mensaje: exactMsg, nombre: 'Usuario', color: '#000000' });
    assert.ok(res, 'Mensaje de 280 caracteres debe ser permitido');
  });
});

