// @req: REQ-012
const assert = require('assert');
const ioClient = require('socket.io-client');

describe('REQ-012 (Integration) — Rechazo de mensajes > 280 chars en Socket.IO', function () {
  this.timeout(5000);
  let socket;
  const port = process.env.PORT || 3000;

  before(function (done) {
    socket = ioClient.connect(`http://localhost:${port}`, { forceNew: true });
    socket.on('connect', done);
  });

  after(function () {
    if (socket && socket.connected) socket.disconnect();
  });

  it('el servidor no debe retransmitir mensajes de más de 280 caracteres', function (done) {
    let received = false;
    const longMsg = 'X'.repeat(300);
    socket.on('Evento-Mensaje-Server', (data) => {
      if (data && data.mensaje && data.mensaje.length > 280) {
        received = true;
      }
    });
    socket.emit('Evento-Mensaje-Server', JSON.stringify({ mensaje: longMsg, nombre: 'TestUser', color: '#111111' }));
    setTimeout(() => {
      assert.strictEqual(received, false, 'El servidor no debió retransmitir mensaje de más de 280 caracteres');
      done();
    }, 600);
  });
});

