// @req: REQ-012
const { test, expect } = require('@playwright/test');

test.describe('REQ-012 (E2E) — Límite de 280 caracteres en navegador', () => {
  test('al enviar mensaje de más de 280 caracteres debe mantener el texto en el campo y notificar', async ({ page }) => {
    await page.goto('/');
    let dialogTriggered = false;
    page.on('dialog', async dialog => {
      dialogTriggered = true;
      await dialog.dismiss();
    });
    const longText = 'C'.repeat(290);
    await page.locator('#m').fill(longText);
    await page.locator('button[type="submit"]').click();
    const val = await page.locator('#m').inputValue();
    expect(val).toBe(longText);
  });
});
